CREATE FUNCTION public.drop_all_foreign_keys(table_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    fk_name text;
BEGIN
    FOR fk_name IN
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = table_name::regclass AND contype = 'f'
    LOOP
        EXECUTE 'ALTER TABLE ' || table_name || ' DROP CONSTRAINT ' || quote_ident(fk_name);
    END LOOP;
END;
$$;


